const tabId = 343605414;
const filtersInfo = await browserjs(tabId, () => {
  // Let's find filter buttons or controls
  const filterElements = Array.from(document.querySelectorAll('button, [role="button"], input, select')).map(el => ({
    tagName: el.tagName,
    type: el.type,
    text: el.textContent?.trim(),
    id: el.id,
    name: el.name,
    className: el.className,
    ariaLabel: el.getAttribute('aria-label')
  })).filter(el => {
    const t = (el.text + ' ' + el.id + ' ' + el.name + ' ' + el.ariaLabel).toLowerCase();
    return t.includes('filter') || t.includes('sex') || t.includes('male') || t.includes('owner') || t.includes('spay') || t.includes('breed') || t.includes('age');
  });
  return filterElements;
});
console.log(JSON.stringify(filtersInfo, null, 2));

